def medmcqa_efficiency_ratio(prompts, completions, answer, **kwargs):
    import math
    groups = {}
    for i, p in enumerate(prompts):
        groups.setdefault(str(p[-1]['content']), []).append(i)

    scores = [0.0] * len(completions)

    for idx in groups.values():
        correct_indices = []
        lengths = []
        for i in idx:
            text = completions[i][0]['content']
            pred = extract_solution(text)
            if is_correct(pred, answer[i]):
                correct_indices.append(i)
                lengths.append(len(text))

        if not correct_indices:
            # All wrong, give neutral or slight penalty based on length
            for i in idx:
                scores[i] = -1.0
            continue

        # Calculate mean and std of lengths for correct answers
        mean_len = sum(lengths) / len(lengths)
        if len(lengths) > 1:
            var = sum((l - mean_len) ** 2 for l in lengths) / len(lengths)
            std_len = math.sqrt(var)
        else:
            std_len = 0.0

        for i in idx:
            text = completions[i][0]['content']
            pred = extract_solution(text)
            if is_correct(pred, answer[i]):
                # Reward shorter correct answers
                # z-score relative to correct group
                z = (len(text) - mean_len) / (std_len + 1e-6)
                # Exponential decay for longer answers
                score = math.exp(-0.1 * z)
                # Cap at 5.0
                scores[i] = min(5.0, score * 3.0)
            else:
                # Wrong answers get penalty, but shorter wrong answers are slightly less bad
                # Simple penalty
                scores[i] = -1.0

    return scores

