    import re
    scores = []
    for completion, gt in zip(completions, answer):
        text = completion[0]['content']

        # Check for closing tags
        has_thinking_close = '</thinking>' in text
        has_solution_close = '</solution>' in text

        # Check if solution tag is present and closed
        solution_match = re.search(r'<solution>(.*?)</solution>', text, re.DOTALL)

        if not has_thinking_close:
            # Missing thinking close tag suggests truncation
            score = -2.0
        elif not has_solution_close:
            # Missing solution close tag suggests truncation
            score = -1.5
        elif solution_match is None:
            # No solution tag at all
            score = -1.0
        else:
            # Check if solution content is empty or just whitespace
            sol_content = solution_match.group(1).strip()
            if not sol_content:
                score = -1.0
            else:
                # Check if it's a valid single letter
                if re.match(r'^[A-Da-d]$', sol_content):
                    score = 0.0
                else:
                    # Malformed solution (e.g., "Answer: A")
                    score = -0.5

        scores.append(score)
    return scores

